fn towerCenter(i: u32) -> vec3f { if (i == 0u) { return vec3f(-6.0, 5.5, -6.0); } if (i == 1u) { return vec3f(6.0, 5.5, -6.0); } if (i == 2u) { return vec3f(-6.0, 5.5, 6.0); } if (i == 3u) { return vec3f(6.0, 5.5, 6.0); } if (i == 4u) { return vec3f(0.0, 6.5, -2.0); } return vec3f(0.0, 4.0, 6.0); }
fn towerRad(i: u32) -> f32 { if (i == 4u) { return 2.5; } if (i == 5u) { return 1.2; } return 1.6; }
fn towerHgt(i: u32) -> f32 { if (i == 4u) { return 9.0; } if (i == 5u) { return 4.0; } return 7.0; }
fn coneHgt(i: u32) -> f32 { if (i == 4u) { return 4.0; } if (i == 5u) { return 2.0; } return 3.0; }
fn placeCastle(index: u32) {
    if (index == 0u) {
        b_hillbuf[0u] = 0.0; b_hillbuf[1u] = 0.0; b_hillbuf[2u] = -2.0; b_hillbuf[3u] = 0.0;
        b_hillbuf[4u] = 0.0; b_hillbuf[5u] = 0.0; b_hillbuf[6u] = 0.0; b_hillbuf[7u] = 1.0;
        b_hillbuf[8u] = 18.0; b_hillbuf[9u] = 4.0; b_hillbuf[10u] = 18.0;
        b_hillbuf[11u] = 0.32; b_hillbuf[12u] = 0.68; b_hillbuf[13u] = 0.3;
    }
    if (index < 6u) {
        let cc = towerCenter(index); let rr = towerRad(index); let hh = towerHgt(index); let ch = coneHgt(index);
        let tb = index * B_towerbuf_STRIDE;
        b_towerbuf[tb + 0u] = 0.0; b_towerbuf[tb + 1u] = cc.x; b_towerbuf[tb + 2u] = cc.y; b_towerbuf[tb + 3u] = cc.z;
        b_towerbuf[tb + 4u] = 0.0; b_towerbuf[tb + 5u] = 0.0; b_towerbuf[tb + 6u] = 0.0; b_towerbuf[tb + 7u] = 1.0;
        b_towerbuf[tb + 8u] = rr; b_towerbuf[tb + 9u] = hh; b_towerbuf[tb + 10u] = rr;
        b_towerbuf[tb + 11u] = 0.86; b_towerbuf[tb + 12u] = 0.78; b_towerbuf[tb + 13u] = 0.62;
        let topY = cc.y + hh * 0.5; let rb = index * B_roofbuf_STRIDE;
        b_roofbuf[rb + 0u] = 0.0; b_roofbuf[rb + 1u] = cc.x; b_roofbuf[rb + 2u] = topY + ch * 0.5; b_roofbuf[rb + 3u] = cc.z;
        b_roofbuf[rb + 4u] = 0.0; b_roofbuf[rb + 5u] = 0.0; b_roofbuf[rb + 6u] = 0.0; b_roofbuf[rb + 7u] = 1.0;
        b_roofbuf[rb + 8u] = rr + 0.5; b_roofbuf[rb + 9u] = ch; b_roofbuf[rb + 10u] = rr + 0.5;
        b_roofbuf[rb + 11u] = 0.92; b_roofbuf[rb + 12u] = 0.28; b_roofbuf[rb + 13u] = 0.4;
    }
    let sb = index * B_stonebuf_STRIDE;
    var px = 0.0; var py = 5.25; var pz = 0.0; var sx = 0.5; var sy = 0.5; var sz = 0.5;
    var cr = 0.85; var cg = 0.78; var cb = 0.62; var qx = 0.0; var qy = 0.0; var qz = 0.0; var qw = 1.0;
    if (index == 0u) { px = -3.5; py = 3.5; pz = 6.0; sx = 5.0; sy = 3.0; sz = 0.6; }
    else if (index == 1u) { px = 3.5; py = 3.5; pz = 6.0; sx = 5.0; sy = 3.0; sz = 0.6; }
    else if (index == 2u) { px = 0.0; py = 3.5; pz = -6.0; sx = 12.0; sy = 3.0; sz = 0.6; }
    else if (index == 3u) { px = -6.0; py = 3.5; pz = 0.0; sx = 0.6; sy = 3.0; sz = 12.0; }
    else if (index == 4u) { px = 6.0; py = 3.5; pz = 0.0; sx = 0.6; sy = 3.0; sz = 12.0; }
    else if (index == 5u) { px = 0.0; py = 2.3; pz = 8.5; sx = 2.2; sy = 0.3; sz = 3.0; cr = 0.45; cg = 0.28; cb = 0.14; }
    else if (index == 6u) { px = 0.0; py = 3.2; pz = 6.0; sx = 1.6; sy = 2.2; sz = 0.4; cr = 0.15; cg = 0.12; cb = 0.15; }
    else if (index == 7u) { px = -0.35; py = 5.2; pz = 6.2; sx = 0.5; sy = 0.5; sz = 0.2; cr = 1.0; cg = 0.3; cb = 0.55; }
    else if (index == 8u) { px = 0.35; py = 5.2; pz = 6.2; sx = 0.5; sy = 0.5; sz = 0.2; cr = 1.0; cg = 0.3; cb = 0.55; }
    else if (index == 9u) { px = 0.0; py = 4.65; pz = 6.2; sx = 0.7; sy = 0.6; sz = 0.2; cr = 1.0; cg = 0.3; cb = 0.55; qz = 0.3826834; qw = 0.9238795; }
    else if (index == 10u) { px = -2.2; py = 2.6; pz = 8.2; sx = 0.8; sy = 0.8; sz = 0.8; cr = 1.0; cg = 0.4; cb = 0.6; }
    else if (index == 11u) { px = 2.2; py = 2.6; pz = 8.2; sx = 0.8; sy = 0.8; sz = 0.8; cr = 1.0; cg = 0.4; cb = 0.6; }
    else if (index < 60u) { let tt = (index - 12u) / 8u; let kk = (index - 12u) - tt * 8u; let ang = f32(kk) * 0.7853982; let rad = towerRad(tt); let ctr = towerCenter(tt); let th = towerHgt(tt); px = ctr.x + rad * cos(ang); pz = ctr.z + rad * sin(ang); py = ctr.y + th * 0.5 + 0.25; sx = 0.5; sy = 0.5; sz = 0.5; }
    else { let seg = (index - 60u) / 4u; let kk2 = (index - 60u) - seg * 4u; let ff = f32(kk2); py = 5.25; sx = 0.5; sy = 0.5; sz = 0.5; if (seg == 0u) { px = -5.5 + ff * 1.333; pz = 6.0; } else if (seg == 1u) { px = 1.5 + ff * 1.333; pz = 6.0; } else if (seg == 2u) { px = -4.5 + ff * 3.0; pz = -6.0; } else if (seg == 3u) { px = -6.0; pz = -4.5 + ff * 3.0; } else { px = 6.0; pz = -4.5 + ff * 3.0; } }
    b_stonebuf[sb + 0u] = 0.0; b_stonebuf[sb + 1u] = px; b_stonebuf[sb + 2u] = py; b_stonebuf[sb + 3u] = pz;
    b_stonebuf[sb + 4u] = qx; b_stonebuf[sb + 5u] = qy; b_stonebuf[sb + 6u] = qz; b_stonebuf[sb + 7u] = qw;
    b_stonebuf[sb + 8u] = sx; b_stonebuf[sb + 9u] = sy; b_stonebuf[sb + 10u] = sz;
    b_stonebuf[sb + 11u] = cr; b_stonebuf[sb + 12u] = cg; b_stonebuf[sb + 13u] = cb;
}

fn wavePennants(index: u32) {
    var bx: f32 = 0.0;
    var by: f32 = 12.4;
    var bz: f32 = 0.0;
    if (index == 0u) { bx = -6.0; by = 12.4; bz = -6.0; }
    else if (index == 1u) { bx = 6.0; by = 12.4; bz = -6.0; }
    else if (index == 2u) { bx = -6.0; by = 12.4; bz = 6.0; }
    else if (index == 3u) { bx = 6.0; by = 12.4; bz = 6.0; }
    else if (index == 4u) { bx = 0.0; by = 16.0; bz = 0.0; }
    else { bx = 0.0; by = 10.0; bz = 7.5; }
    let fi = f32(index);
    let w = sim.time * 6.0 + fi * 1.7;
    let s1 = sin(w);
    let s2 = sin(w * 1.7 + 0.9);
    let s3 = sin(w * 2.3 + 0.4);
    let yaw = 0.35 * s1 + 0.25 * s3 + fi * 0.12;
    let hy = yaw * 0.5;
    let qy = sin(hy);
    let qw = cos(hy);
    let qx = 0.12 * s2;
    let qlen = sqrt(qx * qx + qy * qy + qw * qw + 0.00001);
    let nqx = qx / qlen;
    let nqy = qy / qlen;
    let nqw = qw / qlen;
    let ext = 0.65 + 0.22 * s1 + 0.08 * s2;
    let px = bx + ext;
    let py = by + 0.18 + 0.12 * s2;
    let pz = bz + 0.18 * s3;
    let sx = 0.32;
    let sy = 0.26 + 0.08 * s2;
    let sz = 0.95 + 0.35 * s1;
    let base = index * B_flagbuf_STRIDE;
    b_flagbuf[base + 0u] = 0.0;
    b_flagbuf[base + 1u] = px;
    b_flagbuf[base + 2u] = py;
    b_flagbuf[base + 3u] = pz;
    b_flagbuf[base + 4u] = nqx;
    b_flagbuf[base + 5u] = nqy;
    b_flagbuf[base + 6u] = 0.0;
    b_flagbuf[base + 7u] = nqw;
    b_flagbuf[base + 8u] = sx;
    b_flagbuf[base + 9u] = sy;
    b_flagbuf[base + 10u] = sz;
    b_flagbuf[base + 11u] = 1.0;
    b_flagbuf[base + 12u] = 0.36;
    b_flagbuf[base + 13u] = 0.58;
}

fn placePennants(index: u32) {
    let base = index * B_flagbuf_STRIDE;
    var px: f32 = 0.0;
    var py: f32 = 12.4;
    var pz: f32 = 0.0;
    var sx: f32 = 0.6;
    var sy: f32 = 0.75;
    var sz: f32 = 0.6;
    if (index == 0u) {
        px = -6.0;
        pz = -6.0;
        py = 12.4;
    } else if (index == 1u) {
        px = 6.0;
        pz = -6.0;
        py = 12.4;
    } else if (index == 2u) {
        px = -6.0;
        pz = 6.0;
        py = 12.4;
    } else if (index == 3u) {
        px = 6.0;
        pz = 6.0;
        py = 12.4;
    } else if (index == 4u) {
        px = 0.0;
        pz = 0.0;
        py = 15.4;
        sx = 0.75;
        sy = 0.95;
        sz = 0.75;
    } else {
        px = 0.0;
        pz = 7.2;
        py = 10.4;
        sx = 0.5;
        sy = 0.6;
        sz = 0.5;
    }
    b_flagbuf[base + 0u] = 0.0;
    b_flagbuf[base + 1u] = px;
    b_flagbuf[base + 2u] = py;
    b_flagbuf[base + 3u] = pz;
    b_flagbuf[base + 4u] = 0.0;
    b_flagbuf[base + 5u] = 0.0;
    b_flagbuf[base + 6u] = 0.0;
    b_flagbuf[base + 7u] = 1.0;
    b_flagbuf[base + 8u] = sx;
    b_flagbuf[base + 9u] = sy;
    b_flagbuf[base + 10u] = sz;
    b_flagbuf[base + 11u] = 1.0;
    b_flagbuf[base + 12u] = 0.36;
    b_flagbuf[base + 13u] = 0.58;
}

fn hashQ(q: vec2<f32>) -> f32 {
    let d = fract(sin(dot(q, vec2<f32>(127.1, 311.7))) * 43758.5453);
    return d;
}
fn paintSky(uv: vec2<f32>) -> vec4<f32> {
    let h = 1.0 - uv.y;
    let zen = vec3<f32>(0.30, 0.54, 0.92);
    let mid = vec3<f32>(0.55, 0.76, 0.98);
    let hor = vec3<f32>(1.0, 0.84, 0.82);
    let low = vec3<f32>(0.98, 0.90, 0.80);
    var col = mix(hor, mid, smoothstep(0.42, 0.65, h));
    col = mix(col, zen, smoothstep(0.62, 0.95, h));
    col = mix(low, col, smoothstep(0.28, 0.46, h));
    let sun = vec2<f32>(0.74, 0.68);
    let sd = vec2<f32>((uv.x - sun.x) * camera.aspect, h - sun.y);
    let dist = length(sd);
    let disc = smoothstep(0.055, 0.045, dist);
    let glow = exp(-dist * 7.0) * 0.55 + exp(-dist * 2.6) * 0.22;
    col += vec3<f32>(1.0, 0.92, 0.78) * glow;
    col = mix(col, vec3<f32>(1.0, 0.98, 0.92), disc * 0.95);
    var cm = 0.0;
    for (var k = 0; k < 8; k++) {
        if (k >= 5) {
            break;
        }
        let fk = f32(k);
        let cx = 0.08 + fk * 0.19 + 0.03 * sin(fk * 12.7);
        let cy = 0.58 + 0.075 * sin(fk * 3.3 + 1.0) + fk * 0.018;
        let sx = 0.16 + 0.05 * hashQ(vec2<f32>(fk, 1.0));
        let sy = 0.032 + 0.018 * hashQ(vec2<f32>(fk, 7.0));
        let wob = 0.008 * sin(uv.x * 40.0 + fk * 9.0) * sin(h * 90.0);
        let dd = vec2<f32>((uv.x - cx) * camera.aspect / sx, (h - cy + wob) / sy);
        let e = length(dd);
        let puff = smoothstep(1.0, 0.35, e);
        cm = max(cm, puff);
    }
    let shade = 0.92 + 0.08 * sin(uv.x * 22.0 + h * 30.0);
    let cloudCol = vec3<f32>(1.0, 0.96, 0.95) * shade;
    let pinkUnder = vec3<f32>(1.0, 0.82, 0.86);
    var flat = mix(pinkUnder, cloudCol, smoothstep(0.0, 0.75, cm));
    let alpha = smoothstep(0.12, 0.85, cm) * smoothstep(0.38, 0.52, h) * (1.0 - smoothstep(0.86, 0.98, h));
    col = mix(col, flat, alpha * 0.92);
    let sparkle = hashQ(floor(vec2<f32>(uv.x * 320.0, h * 320.0)));
    let star = smoothstep(0.995, 1.0, sparkle) * smoothstep(0.85, 0.98, h) * 0.35;
    col += vec3<f32>(star);
    return vec4<f32>(col, 1.0);
}
